describe('Video Modal', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.get('.open-modal-button').click(); // Replace with the actual selector to open the modal
    });

    it('should pause the video when the modal is closed', () => {
        cy.get('.modal-close-button').click(); // Replace with the actual selector for closing the modal
        cy.get('video').then(($video) => {
            const isPaused = $video[0].paused;
            expect(isPaused).to.be.true; // Verify that the video is paused
        });
    });

    it('should keep the video playing when the modal is not closed', () => {
        cy.get('video').then(($video) => {
            const isPlayingBeforeClose = !$video[0].paused;
            expect(isPlayingBeforeClose).to.be.true; // Verify that the video is playing before closing
        });
        cy.get('.modal-close-button').click(); // Close the modal
        cy.get('video').then(($video) => {
            const isPausedAfterClose = $video[0].paused;
            expect(isPausedAfterClose).to.be.true; // Verify that the video is paused after closing
        });
    });
});
